mapper.select:
SELECT  FROM pair_runs
WHERE workspace_id = #{workspaceId} AND iteration_id = #{iterationId}
ORDER BY started_at DESC LIMIT 1

mapper.update:
UPDATE pair_runs SET lease_expires_at = #{expiresAt}, updated_at = #{timestamp}
WHERE id = #{id} AND version = #{expectedVersion} AND status = 'running'
  AND lease_token_sha256 = #{tokenSha256} AND lease_expires_at > #{timestamp}

mapper.select:
SELECT  FROM showcase_runs
WHERE workspace_id = #{workspaceId} AND iteration_id = #{iterationId}
ORDER BY attempt DESC LIMIT 1

mapper.update:
UPDATE showcase_runs SET stage = #{row.stage}, version = #{row.version},
  evidence_bundle_sha256 = #{row.evidenceBundleSha256}, updated_at = #{row.updatedAt},
  completed_at = #{row.completedAt}
WHERE id = #{row.id} AND workspace_id = #{row.workspaceId} AND version = #{expectedVersion}
